"use strict"
    ; // This directive enables strict mode for the entire script.

 /*
  * The 'input' parameter of the Main function will receive the complete input data string.
  * This is a critical point for understanding the program's flow.
  */

function Main
(
    input
)
{
    let
        result
        =
        0
    ; // Initialize a variable to hold our computed result. Starts at zero.

    /*
     * Process each character of the input string.
     * The input string is first split into an array of individual characters.
     * Then, for each character 'e', we perform an operation.
     */
    input . split ( "" ) . forEach ( e =>
    {
        // If the character is a plus sign, increment the result.
        if ( e == "+" ) result ++ ;

        // If the character is a minus sign, decrement the result.
        if ( e == "-" ) result -- ;
    }
    )
    ; // End of the forEach loop and arrow function.

    // Finally, print the calculated result to the console.
    console . log ( result ) ;
}
