// This is a comment that spans across multiple lines.
// It's just to demonstrate comment variations.
// This is a comment.
// Another one.

"use strict"; // Ensure strict mode is active.

/*
 * This program takes an input string consisting of '+' and '-' characters
 * and calculates a final result by incrementing for each '+' and decrementing for each '-'.
 */
function Main(input) {
  let result = 0; // Initialize result counter.

  // Split the input string into an array of characters and iterate through each one.
  input.split("").forEach(e => {
    // Check if the current character is a plus sign.
    if (e == "+") {
      result++; // Increment the result if it is.
    }

    // Check if the current character is a minus sign.
    if (e == "-") {
      result--; // Decrement the result if it is.
    }
  });

  // Output the final calculated result to the standard output.
  console.log(result);
}

